// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ============================================================
// SECURITY MIDDLEWARE
// ============================================================

// 1. Security headers with Helmet
app.use(helmet());

// 2. Rate limiting to prevent brute force/DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// 3. CORS configuration (restrict to specific origins in production)
const cors = require('cors');
const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];
app.use(cors({
  origin: allowedOrigins,
  credentials: true,
  optionsSuccessStatus: 200,
}));

// 4. Request body parsing with size limits to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - ${res.statusCode} (${duration}ms)`);
  });
  next();
});

// ============================================================
// ROUTES
// ============================================================

app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Protected endpoint example (would need actual auth implementation)
app.get('/users', authenticateUser, (req, res) => {
  try {
    // Input validation for query parameters
    const limit = validateLimit(req.query.limit);
    const offset = validateOffset(req.query.offset);

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      total: users.length,
      limit,
      offset,
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(400).json({ error: 'Invalid request parameters' });
  }
});

// ============================================================
// VALIDATION HELPERS
// ============================================================

/**
 * Validates and sanitizes the limit parameter
 * @param {*} limit - The limit value from query params
 * @returns {number} - Validated limit (1-100)
 */
function validateLimit(limit) {
  const parsed = parseInt(limit, 10);

  if (isNaN(parsed)) {
    return 10; // default
  }

  // Ensure limit is between 1 and 100
  return Math.max(1, Math.min(100, parsed));
}

/**
 * Validates and sanitizes the offset parameter
 * @param {*} offset - The offset value from query params
 * @returns {number} - Validated offset (non-negative)
 */
function validateOffset(offset) {
  const parsed = parseInt(offset, 10);

  if (isNaN(parsed)) {
    return 0; // default
  }

  // Ensure offset is non-negative
  return Math.max(0, parsed);
}

/**
 * Placeholder authentication middleware
 * In production, implement proper JWT or session-based auth
 */
function authenticateUser(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Unauthorized: Missing authentication token' });
  }

  // TODO: Verify token validity
  // For now, just a placeholder
  try {
    // Validate token format
    if (typeof token !== 'string' || token.length === 0) {
      throw new Error('Invalid token format');
    }
    next();
  } catch (error) {
    console.error('Authentication error:', error);
    res.status(401).json({ error: 'Unauthorized: Invalid token' });
  }
}

// ============================================================
// ERROR HANDLING
// ============================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Don't leak error details to client in production
  const isDevelopment = process.env.NODE_ENV === 'development';
  const errorMessage = isDevelopment ? err.message : 'Internal server error';

  res.status(err.status || 500).json({
    error: errorMessage,
    ...(isDevelopment && { stack: err.stack }),
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Optionally exit process or send alert
});

// ============================================================
// SERVER STARTUP
// ============================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

