## Security Best Practices Applied

1. **Principle of Least Privilege**: Default-deny approach; only expose what's necessary
2. **Defense in Depth**: Multiple layers of security (headers, rate limits, validation, auth)
3. **Fail Securely**: Errors don't expose stack traces or internal details in production
4. **Input Validation**: All user input is validated before use
5. **Rate Limiting**: Protects against DoS and brute force
6. **Audit Logging**: All requests logged for compliance and incident investigation
7. **Secure Headers**: Protection against common web vulnerabilities
8. **Error Handling**: Centralized, consistent error responses

---

## References

- OWASP Top 10: https://owasp.org/www-project-top-ten/
- Express Security Best Practices: https://expressjs.com/en/advanced/best-practice-security.html
- Helmet.js Documentation: https://helmetjs.github.io/
- Express Rate Limit: https://github.com/nfriedly/express-rate-limit
- NIST Cybersecurity Framework: https://www.nist.gov/cyberframework

/**
 * Improved Express Application with Security Best Practices
 *
 * Security enhancements:
 * - Helmet middleware for security headers
 * - CORS configuration
 * - Rate limiting (global + per-endpoint)
 * - Request logging
 * - Input size limits and validation
 * - Error handling middleware
 * - Authentication checks
 * - Sensitive data filtering
 * - Request timeouts
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const cors = require('cors');

const app = express();
const env = process.env.NODE_ENV || 'development';

// ===== SECURITY MIDDLEWARE =====

// 1. Security Headers (Helmet)
// Protects against: clickjacking, MIME type sniffing, XSS, MITM
app.use(helmet());

// 2. CORS Configuration
// Restricts cross-origin requests to approved origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};
app.use(cors(corsOptions));

// 3. Global Rate Limiting
// Protects against: DoS, brute force, scraping
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                   // 100 requests per IP per window
  standardHeaders: true,      // Return rate limit info in headers
  legacyHeaders: false,       // Disable X-RateLimit-* headers
  message: 'Too many requests, please try again later.',
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too many requests. Please try again later.',
      retryAfter: req.rateLimit.resetTime,
    });
  },
});
app.use(globalLimiter);

// 4. Request Logging
// Helps detect suspicious activity and support incident response
app.use(morgan(env === 'production' ? 'combined' : 'dev', {
  skip: (req) => req.path === '/health', // Don't log health checks
}));

// 5. Request Body Parsing with Size Limits
// Protects against: billion-byte DoS attacks, memory exhaustion
app.use(express.json({
  limit: '10kb', // Strict limit for API
  verify: (req, res, buf) => {
    // Additional verification can be added here
    // e.g., SHA256 hash for signature verification
  },
}));
app.use(express.urlencoded({
  limit: '10kb',
  extended: true,
  parameterLimit: 50, // Limit number of parameters
}));

// 6. Content-Type Validation
// Prevents unexpected input formats
app.use((req, res, next) => {
  if (req.method !== 'GET' && req.method !== 'HEAD' && req.method !== 'OPTIONS') {
    const contentType = req.get('Content-Type');
    if (contentType && !contentType.includes('application/json')) {
      return res.status(415).json({
        error: 'Unsupported Media Type. Expected application/json.'
      });
    }
  }
  next();
});

// 7. Hide Express Version
// Prevents information disclosure to attackers
app.disable('x-powered-by');

// ===== AUTHENTICATION MIDDLEWARE =====

/**
 * Placeholder authentication middleware
 * Replace with real implementation (JWT, OAuth, API keys, etc.)
 */
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    return res.status(401).json({
      error: 'Unauthorized. Missing or invalid authorization token.'
    });
  }

  try {
    // TODO: Verify and decode token
    // Example with JWT:
    // const decoded = jwt.verify(token, process.env.JWT_SECRET);
    // req.user = decoded;

    // Temporary: mock authenticated user
    req.user = { id: 1, role: 'user' };
    next();
  } catch (error) {
    return res.status(403).json({
      error: 'Forbidden. Invalid or expired token.'
    });
  }
};

// ===== ROUTES =====

/**
 * Health Check Endpoint
 * Purpose: System monitoring, load balancer health checks
 *
 * Security considerations:
 * - Minimal response data
 * - No sensitive information
 * - Rate limited globally but not individually (health checks important for monitoring)
 */
app.get('/health', (req, res) => {
  try {
    res.set('Content-Type', 'application/json');
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      // Add minimal system info for monitoring
      // uptime: process.uptime(),
    });
  } catch (error) {
    // Health endpoint should still return 200 even if partially degraded
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Get Users Endpoint
 * Purpose: Retrieve list of users (metadata only, no sensitive data)
 *
 * Security requirements:
 * - Authentication required
 * - Strict rate limiting (prevent scraping)
 * - Sensitive fields removed (emails, personal data)
 * - Error handling to prevent stack trace leaks
 * - Input validation (if filters added in future)
 */
const userLimiter = rateLimit({
  windowMs: 1 * 60 * 1000, // 1 minute
  max: 5,                    // 5 requests per IP per minute (stricter than global)
  skipSuccessfulRequests: true, // Don't count successful requests
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too many requests. Please try again in 1 minute.',
    });
  },
});

app.get('/users', userLimiter, authenticateToken, (req, res) => {
  try {
    // Validate query parameters (if added in future)
    const { filter, page } = req.query;

    // Return only non-sensitive user information
    // In production, this would come from a database with proper authorization checks
    const users = [
      { id: 1, name: 'Alice' },        // ✓ Safe: public name only
      { id: 2, name: 'Bob' },          // ✓ Safe: public name only
      // ✗ REMOVED: email addresses
      // ✗ REMOVED: phone numbers
      // ✗ REMOVED: physical addresses
      // ✗ REMOVED: payment information
    ];

    res.set('Content-Type', 'application/json');
    res.json(users);
  } catch (error) {
    console.error('Error fetching users:', error);

    // Don't expose stack trace to client
    const status = error.status || 500;
    const message = env === 'production'
      ? 'Internal server error'
      : error.message;

    res.status(status).json({ error: message });
  }
});

// ===== ERROR HANDLING =====

/**
 * 404 Handler
 * Handles requests to undefined routes
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method,
  });
});

/**
 * Global Error Handling Middleware
 * Must be last; catches all errors from route handlers
 *
 * Security principles:
 * - Don't expose stack traces in production
 * - Log errors for debugging/incident response
 * - Return safe, generic errors to clients
 * - Include request ID for tracing
 */
app.use((err, req, res, next) => {
  const requestId = req.id || 'unknown';
  const status = err.status || err.statusCode || 500;

  // Log error details (for debugging in development/logs)
  console.error(JSON.stringify({
    timestamp: new Date().toISOString(),
    requestId,
    method: req.method,
    path: req.path,
    status,
    error: err.message,
    stack: err.stack,
  }));

  // Return safe response to client
  const clientMessage = env === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(status).json({
    error: clientMessage,
    requestId, // For support and debugging
  });
});

// ===== SERVER STARTUP =====

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`[${env}] Server running on port ${PORT}`);
  console.log(`[${env}] CORS origins: ${corsOptions.origin}`);
  console.log(`[${env}] Rate limits: global=${globalLimiter.options.max}/15min, users=${userLimiter.options.max}/1min`);
});

// 8. Request Timeout Configuration
// Protects against: slowloris DoS attacks, hanging connections
server.setTimeout(30 * 1000, (socket) => {
  console.warn('Request timeout - closing socket');
  socket.destroy();
});

server.keepAliveTimeout = 65 * 1000;
server.headersTimeout = 66 * 1000;

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

