// Production-ready Express application with security best practices
// Security features: helmet.js, input validation, authentication, rate limiting,
// error handling, CORS, logging, and proper data sanitization

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const cors = require('cors');
const logger = require('morgan');

const app = express();

// ============================================================
// SECURITY: HTTP Security Headers
// ============================================================
app.use(helmet());

// ============================================================
// SECURITY: CORS Configuration
// ============================================================
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};
app.use(cors(corsOptions));

// ============================================================
// SECURITY: Request Logging
// ============================================================
app.use(logger('combined'));

// ============================================================
// SECURITY: Body Parser with Size Limits
// ============================================================
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================================
// SECURITY: Rate Limiting
// ============================================================
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter limit for sensitive endpoints
  message: 'Too many requests to this endpoint, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(generalLimiter);

// ============================================================
// SECURITY: Mock JWT Authentication
// ============================================================
const mockVerifyToken = (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader) {
      return res.status(401).json({
        error: 'Unauthorized',
        message: 'Missing authorization header',
      });
    }

    const parts = authHeader.split(' ');
    if (parts.length !== 2 || parts[0] !== 'Bearer') {
      return res.status(401).json({
        error: 'Unauthorized',
        message: 'Invalid authorization header format',
      });
    }

    const token = parts[1];

    // Mock JWT validation (in production, use jsonwebtoken library)
    if (!token || token.length < 10) {
      return res.status(401).json({
        error: 'Unauthorized',
        message: 'Invalid or malformed token',
      });
    }

    // Store user info for downstream handlers
    req.user = { id: 1, role: 'user' };
    next();
  } catch (err) {
    return res.status(500).json({
      error: 'Authentication error',
      message: 'Internal server error during authentication',
    });
  }
};

// ============================================================
// SECURITY: Input Validation Helper
// ============================================================
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(e => ({
        field: e.param,
        message: e.msg,
      })),
    });
  }
  next();
};

// ============================================================
// ROUTES
// ============================================================

// Health check endpoint - no auth required
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
