        total: allUsers.length,
        limit,
        offset
      });
    } catch (err) {
      next(err); // Pass to error handler
    }
  }
);

// ✅ 6. Authentication middleware
function requireAuth(req, res, next) {
  const apiKey = req.headers['x-api-key'];
